from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def intersect(nums1: list[int], nums2: list[int]) -> list[int]:
    counts = Counter(nums1)
    out: list[int] = []
    for value in nums2:
        if counts[value] > 0:
            out.append(value)
            counts[value] -= 1
    return sorted(out)

